def is_email(string): 
   regex = '^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w+$'
   if(re.search(regex,string)): 
      print("Valid Email")  
   else: 
      print("Invalid Email")

### Instruction:
Create a Python program to validate an email address according to RFC5322 syntax.

### Response:
import re
def validate(email):
    regex = r'^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$'
    if re.search(regex, email):
        return True
    else:
        return False

