### Instruction:
Create a simple php website using the following data records.

### Input:
[
  {
    "firstname": "Oliver",
    "lastname": "Smith",
    "address": "1234 Main Street, City, Country"
  },
  {
    "firstname": "John",
    "lastname": "Doe",
    "address": "5678 Long Road, City, Country"
  },
  {
    "firstname": "Chris",
    "lastname": "Fitzgerald",
    "address": "9123 Eagle Street, City, Country"
  }
]

### Response:
<!DOCTYPE html>
<html>
<head>
  <title>Simple PHP Website</title>
</head>
<body>
  <?php
    $data = [
      [
        "firstname" => "Oliver",
        "lastname" => "Smith",
        "address" => "1234 Main Street, City, Country"
      ],
      [
        "firstname" => "John",
        "lastname" => "Doe",
        "address" => "5678 Long Road, City, Country"
      ],
      [
        "firstname" => "Chris",
        "lastname" => "Fitzgerald",
        "address" => "9123 Eagle Street, City, Country"
      ]
    ]; 

    foreach($data as $person) {
      echo '<p>';
      echo $person['firstname'] . ' ' . $person['lastname'] . '<br/>';
      echo $person['address'];
      echo '</p>';
    }
  ?>
</body>
</html>

